// native_tts_register.cpp — registers every native of native_tts_decl.h with
// bronze (embed::registerNative) under __bro_native.tts. Generated by brosurface
// (gen/emit_natives.mjs); do not edit. Call registerNatives_tts from registerBroNatives
// (src/bronze_host/host_natives.h) on the thread that runs the program.
//
// Class members are Function-kind natives taking the handle first (the wrapper's
// receiver is dynamic, so a Method-kind registration would be unreachable from it);
// each class has one Constructor-kind registration, which mints the class, and its
// prototype is published as __bro_native.tts.<Class>Proto for tts.js to chain.

#include "native_tts_decl.h"

#include "embed/embed.h"

#include <initializer_list>
#include <string>

namespace bro::bronze_host {

namespace {

namespace ev = bronze::embed;

ev::NativeSignature sig(const char* ret, std::initializer_list<const char*> params, ev::NativeKind kind) {
    ev::NativeSignature s;
    s.returnType = ret;
    for (const char* p : params) s.paramTypes.emplace_back(p);
    s.kind = kind;
    return s;
}

bool fn(const char* path, void* f, const char* ret, std::initializer_list<const char*> params, std::string* error) {
    return ev::registerNative(path, f, sig(ret, params, ev::NativeKind::Function), error);
}

bool ctor(const char* path, void* f, ev::HandleDestructor dtor, bronze::runtime::Finalize finalize,
          std::initializer_list<const char*> params, std::string* error) {
    ev::NativeSignature s = sig(path, params, ev::NativeKind::Constructor);
    s.className = path;
    s.destructor = dtor;
    s.finalize = finalize;
    return ev::registerNative(path, f, s, error);
}

// The prototype every instance of a class is born on, published where the
// wrapper reads it. Skipped when the roots are not there (bro-native-manifest
// registers without them; the manifest does not need the prototype).
void publishPrototype(const char* ns, const char* className, const char* protoName) {
    ev::GlobalValue root = ev::globalValue("__bro_native");
    if (!root.found || !ev::isObject(root.value)) return;
    ev::GlobalValue proto = ev::nativeClassPrototype(className);
    if (!proto.found) return;
    // Each value rooted before the next allocating call (bronze embed GC contract).
    ev::Persistent rootSlot(root.value);
    ev::Persistent protoSlot(proto.value);
    ev::Persistent nsSlot(ev::getProperty(rootSlot.get(), ns));
    if (!ev::isObject(nsSlot.get())) return;
    ev::setProperty(nsSlot.get(), protoName, protoSlot.get());
}

template <typename F>
void* p(F* f) { return reinterpret_cast<void*>(f); }

}  // namespace

bool registerNatives_tts(std::string* error) {
    bool ok =
        ctor("__bro_native.tts.KokoroModel", p(&bro_tts_KokoroModel_ctor), &bro_tts_KokoroModel_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.tts.Voice", p(&bro_tts_Voice_ctor), &bro_tts_Voice_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.tts.KokoroSession", p(&bro_tts_KokoroSession_ctor), &bro_tts_KokoroSession_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.tts.QwenTtsModel", p(&bro_tts_QwenTtsModel_ctor), &bro_tts_QwenTtsModel_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.tts.QwenTtsSession", p(&bro_tts_QwenTtsSession_ctor), &bro_tts_QwenTtsSession_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.tts.SupertonicModel", p(&bro_tts_SupertonicModel_ctor), &bro_tts_SupertonicModel_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.tts.SupertonicVoice", p(&bro_tts_SupertonicVoice_ctor), &bro_tts_SupertonicVoice_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.tts.SpeakerEncoder", p(&bro_tts_SpeakerEncoder_ctor), &bro_tts_SpeakerEncoder_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        fn("__bro_native.tts.KokoroModel_loaded_get", p(&bro_tts_KokoroModel_loaded_get), "bool", {"__bro_native.tts.KokoroModel"}, error) &&
        fn("__bro_native.tts.KokoroModel_device_get", p(&bro_tts_KokoroModel_device_get), "str", {"__bro_native.tts.KokoroModel"}, error) &&
        fn("__bro_native.tts.KokoroModel_loadVoice", p(&bro_tts_KokoroModel_loadVoice), "__bro_native.tts.Voice", {"__bro_native.tts.KokoroModel", "str"}, error) &&
        fn("__bro_native.tts.KokoroModel_createSession", p(&bro_tts_KokoroModel_createSession), "__bro_native.tts.KokoroSession", {"__bro_native.tts.KokoroModel"}, error) &&
        fn("__bro_native.tts.Voice_loaded_get", p(&bro_tts_Voice_loaded_get), "bool", {"__bro_native.tts.Voice"}, error) &&
        fn("__bro_native.tts.Voice_name_get", p(&bro_tts_Voice_name_get), "str", {"__bro_native.tts.Voice"}, error) &&
        fn("__bro_native.tts.KokoroSession_loaded_get", p(&bro_tts_KokoroSession_loaded_get), "bool", {"__bro_native.tts.KokoroSession"}, error) &&
        fn("__bro_native.tts.KokoroSession_reset", p(&bro_tts_KokoroSession_reset), "void", {"__bro_native.tts.KokoroSession"}, error) &&
        fn("__bro_native.tts.QwenTtsModel_loaded_get", p(&bro_tts_QwenTtsModel_loaded_get), "bool", {"__bro_native.tts.QwenTtsModel"}, error) &&
        fn("__bro_native.tts.QwenTtsModel_device_get", p(&bro_tts_QwenTtsModel_device_get), "str", {"__bro_native.tts.QwenTtsModel"}, error) &&
        fn("__bro_native.tts.QwenTtsModel_variant_get", p(&bro_tts_QwenTtsModel_variant_get), "str", {"__bro_native.tts.QwenTtsModel"}, error) &&
        fn("__bro_native.tts.QwenTtsModel_createSession", p(&bro_tts_QwenTtsModel_createSession), "__bro_native.tts.QwenTtsSession", {"__bro_native.tts.QwenTtsModel"}, error) &&
        fn("__bro_native.tts.QwenTtsSession_loaded_get", p(&bro_tts_QwenTtsSession_loaded_get), "bool", {"__bro_native.tts.QwenTtsSession"}, error) &&
        fn("__bro_native.tts.QwenTtsSession_variant_get", p(&bro_tts_QwenTtsSession_variant_get), "str", {"__bro_native.tts.QwenTtsSession"}, error) &&
        fn("__bro_native.tts.QwenTtsSession_reset", p(&bro_tts_QwenTtsSession_reset), "void", {"__bro_native.tts.QwenTtsSession"}, error) &&
        fn("__bro_native.tts.SupertonicModel_loaded_get", p(&bro_tts_SupertonicModel_loaded_get), "bool", {"__bro_native.tts.SupertonicModel"}, error) &&
        fn("__bro_native.tts.SupertonicModel_device_get", p(&bro_tts_SupertonicModel_device_get), "str", {"__bro_native.tts.SupertonicModel"}, error) &&
        fn("__bro_native.tts.SupertonicModel_loadVoiceStyle", p(&bro_tts_SupertonicModel_loadVoiceStyle), "__bro_native.tts.SupertonicVoice", {"__bro_native.tts.SupertonicModel", "str"}, error) &&
        fn("__bro_native.tts.SupertonicVoice_loaded_get", p(&bro_tts_SupertonicVoice_loaded_get), "bool", {"__bro_native.tts.SupertonicVoice"}, error) &&
        fn("__bro_native.tts.SupertonicVoice_name_get", p(&bro_tts_SupertonicVoice_name_get), "str", {"__bro_native.tts.SupertonicVoice"}, error) &&
        fn("__bro_native.tts.SpeakerEncoder_loaded_get", p(&bro_tts_SpeakerEncoder_loaded_get), "bool", {"__bro_native.tts.SpeakerEncoder"}, error) &&
        fn("__bro_native.tts.SpeakerEncoder_device_get", p(&bro_tts_SpeakerEncoder_device_get), "str", {"__bro_native.tts.SpeakerEncoder"}, error);
#if BRO_WITH_SOUNDML
    ok = ok &&
        fn("__bro_native.tts.init", p(&bro_tts_init), "void", {}, error) &&
        fn("__bro_native.tts.setAssetRoot", p(&bro_tts_setAssetRoot), "void", {"str"}, error) &&
        fn("__bro_native.tts.setAssets", p(&bro_tts_setAssets), "void", {"bool", "str", "bool", "str", "bool", "str", "bool", "str"}, error);
#endif
    if (!ok) return false;
    publishPrototype("tts", "__bro_native.tts.KokoroModel", "KokoroModelProto");
    publishPrototype("tts", "__bro_native.tts.Voice", "VoiceProto");
    publishPrototype("tts", "__bro_native.tts.KokoroSession", "KokoroSessionProto");
    publishPrototype("tts", "__bro_native.tts.QwenTtsModel", "QwenTtsModelProto");
    publishPrototype("tts", "__bro_native.tts.QwenTtsSession", "QwenTtsSessionProto");
    publishPrototype("tts", "__bro_native.tts.SupertonicModel", "SupertonicModelProto");
    publishPrototype("tts", "__bro_native.tts.SupertonicVoice", "SupertonicVoiceProto");
    publishPrototype("tts", "__bro_native.tts.SpeakerEncoder", "SpeakerEncoderProto");
    return true;
}

}  // namespace bro::bronze_host
